const HASHTAG = {
  'Yapay Zeka': '#YapayZeka',
  'Teknoloji': '#Teknoloji',
  'Güvenlik': '#SiberGuvenlik',
  'AI': '#YapayZeka',
  'Technology': '#Teknoloji',
  'Security': '#SiberGuvenlik',
  'Siber': '#SiberGuvenlik',
};

const EMOJI = {
  'Yapay Zeka': '🤖',
  'AI': '🤖',
  'Teknoloji': '💻',
  'Technology': '💻',
  'Güvenlik': '🔒',
  'Security': '🔒',
  'Siber': '🔒',
};

const TCO_LEN = 23;
const LIMIT = 280;
const CTA = 'Devamı için ⬇️';

function pickEmoji(kategori) {
  const k = String(kategori || '');
  if (EMOJI[k]) return EMOJI[k];
  const lower = k.toLowerCase();
  if (lower.includes('yapay') || lower.includes('ai')) return '🤖';
  if (lower.includes('teknoloji') || lower.includes('technology')) return '💻';
  if (lower.includes('güvenlik') || lower.includes('guvenlik') || lower.includes('security') || lower.includes('siber')) return '🔒';
  return '📰';
}

function weightedLen(emoji, title, summary, tag) {
  // emoji + ' ' + title + '\n\n' + summary + '\n\n' + 'Devamı için ⬇️\n' + link + '\n\n' + tag
  // emoji=2, ⬇️=2, link=23; other JS string lengths at 1
  const ctaPrefix = 'Devamı için '; // without arrow
  return (
    2 + // start emoji
    1 + // space after emoji
    title.length +
    2 + // \n\n after title
    summary.length +
    2 + // \n\n after summary
    ctaPrefix.length +
    2 + // ⬇️
    1 + // \n after CTA
    TCO_LEN +
    2 + // \n\n before tag
    tag.length
  );
}

function buildTweet(row) {
  const emoji = pickEmoji(row.kategori);
  const tag = HASHTAG[row.kategori] || (String(row.kategori || '').toLowerCase().includes('siber') ? '#SiberGuvenlik' : '#Teknoloji');
  let t = String(row.post_title || '').trim();
  let s = String(row.post_summary || '').trim();
  const link = String(row.post_link || '').trim();

  // Fixed weighted cost excluding title+summary
  const fixed = weightedLen(emoji, '', '', tag);
  let budget = LIMIT - fixed;
  if (budget < 20) budget = 20;

  // Trim summary first, then title
  if (t.length + s.length > budget) {
    const leftForSummary = budget - t.length;
    if (leftForSummary < 0) {
      // title alone overflows: trim title first to leave a bit for summary if any
      const titleMax = Math.max(20, budget - 4);
      if (t.length > titleMax) {
        t = t.slice(0, Math.max(1, titleMax - 3)).trimEnd() + '...';
      }
      const rem = budget - t.length;
      if (rem <= 4) {
        s = '';
      } else if (s.length > rem) {
        s = s.slice(0, Math.max(1, rem - 3)).trimEnd() + '...';
      }
    } else if (s.length > leftForSummary) {
      if (leftForSummary <= 4) {
        s = '';
        // still over? trim title
        if (t.length > budget) {
          t = t.slice(0, Math.max(1, budget - 3)).trimEnd() + '...';
        }
      } else {
        s = s.slice(0, Math.max(1, leftForSummary - 3)).trimEnd() + '...';
      }
    }
  }

  // Final safety: if still over, shrink title
  let w = weightedLen(emoji, t, s, tag);
  while (w > LIMIT && t.length > 4) {
    t = t.slice(0, Math.max(1, t.length - 4)).trimEnd() + '...';
    w = weightedLen(emoji, t, s, tag);
  }
  while (w > LIMIT && s.length > 0) {
    if (s.length <= 4) s = '';
    else s = s.slice(0, Math.max(1, s.length - 4)).trimEnd() + '...';
    w = weightedLen(emoji, t, s, tag);
  }

  const text = emoji + ' ' + t + '\n\n' + s + '\n\n' + CTA + '\n' + link + '\n\n' + tag;

  return { text, weighted_len: weightedLen(emoji, t, s, tag), hashtag: tag, emoji };
}

return $input.all().map((item) => {
  const row = item.json;
  const built = buildTweet(row);
  return {
    json: {
      ...row,
      tweet_text: built.text,
      tweet_weighted_len: built.weighted_len,
      hashtag: built.hashtag,
      emoji: built.emoji,
    },
  };
});

const items = $input.all();
const rows = items
  .map(i => i.json)
  .filter(j => j && j.id != null && j.id !== '' && !j.success);
// Some n8n postgres versions wrap rows differently
const flat = [];
for (const j of items.map(i => i.json)) {
  if (Array.isArray(j)) { flat.push(...j); continue; }
  if (j && Array.isArray(j.rows)) { flat.push(...j.rows); continue; }
  if (j && j.id != null && j.id !== '') flat.push(j);
}
if (flat.length === 0) {
  return [{ json: { id: null, empty: true } }];
}
return flat.map(r => ({ json: { ...r, id: Number(r.id) } }));

const row = $json;
const tweetText = String(row.tweet_text || '').trim();
if (!tweetText) {
  throw new Error('tweet_text missing for queue id ' + row.id);
}

const encoded = encodeURIComponent(tweetText);
const clickUrl = `https://x.com/intent/post?text=${encoded}`;
const title = String(row.post_title || 'Yeni yazı').trim();
const body = `${title}\n\nGöndermek için dokun`;

return [{
  json: {
    ...row,
    ntfy_topic: 'bilisimpostasi-tw-x7k2m9qz',
    ntfy_url: 'https://ntfy.sh/bilisimpostasi-tw-x7k2m9qz',
    ntfy_title: 'Bilişim Postası — Yeni Tweet Hazır',
    ntfy_click: clickUrl,
    ntfy_icon: 'https://bilisimpostasi.com.tr/navbar-logo.png',
    ntfy_body: body,
  },
}];

